import React from "react";

import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend
} from "recharts";

const data = [
  {
    name: "Page 1",
    LIGNE_J: 4000,
    RER_A: 2400,
    amt: 2400
  },
  {
    name: "Page 2",
    LIGNE_J: 3490,
    RER_A: 4300,
    amt: 2100
  }
];

export default function Graph() {
  return (
    <LineChart width={200} height={200} data={data}
    margin={{
        top: 5,
        right: 30,
        left: 20,
        bottom: 5
      }}>
      <CartesianGrid strokeDasharray="3 3" />
      <XAxis dataKey="name" />
      <YAxis />
      <Tooltip />
      <Legend />
      <Line type="monotone" dataKey="RER_A" stroke="#ff0000" activeDot={{ r: 7 }}/>
      <Line type="monotone" dataKey="LIGNE_J" stroke="#82ca9d" activeDot={{ r: 7 }}/>
    </LineChart>
  );
}
